.shell {
  display: flex;
  flex-direction: column;
  width: 100%;
  min-width: 0;
  height: 680px;
  min-height: 480px;
  overflow: clip;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--surface);
  color: var(--foreground);
  container: workspace-shell / inline-size;
  font-size: 14px;
  line-height: 20px;
}
.header {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
  min-height: var(--workspace-header-height);
  padding: 0 12px;
  border-bottom: 1px solid var(--border);
}
.title {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 14px;
  font-weight: 500;
}
.layout {
  display: flex;
  flex: 1;
  min-height: 0;
  min-width: 0;
}
.sidebar {
  flex-shrink: 0;
  width: var(--workspace-sidebar-collapsed);
  overflow: auto;
  border-right: 1px solid var(--border);
  background: var(--background);
  container: workspace-navigation / inline-size;
}
.sidebarToggle {
  display: none;
}
.main {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  min-width: 0;
}
.toolbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  min-height: 40px;
  flex-shrink: 0;
  padding: 0 12px;
  border-bottom: 1px solid var(--border);
}
.content {
  flex: 1;
  min-height: 0;
  min-width: 0;
  overflow: auto;
}
.inspector {
  position: relative;
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  width: var(--inspector-current-width, var(--workspace-inspector-width));
  min-width: var(--workspace-inspector-min);
  max-width: var(--workspace-inspector-max);
  border-left: 1px solid var(--border);
}
.inspectorHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 48px;
  flex-shrink: 0;
  padding: 0 16px;
  border-bottom: 1px solid var(--border);
}
.inspectorHeader h2 {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 14px;
  line-height: 20px;
  font-weight: 500;
}
.inspectorBody {
  min-height: 0;
  flex: 1;
  overflow: auto;
}
.inspectorFooter {
  min-height: 56px;
  flex-shrink: 0;
  padding: 12px;
  border-top: 1px solid var(--border);
}
.resizeHandle {
  position: absolute;
  top: 0;
  bottom: 0;
  left: -4px;
  width: 8px;
  z-index: 1;
  cursor: col-resize;
  touch-action: none;
}
.resizeHandle:hover,
.resizeHandle:focus-visible {
  background: color-mix(in srgb, var(--primary) 25%, transparent);
}
.resizeHandle:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: -2px;
}
.bottom {
  position: relative;
  flex-shrink: 0;
  height: var(--workspace-bottom-height);
  min-height: 200px;
  max-height: 400px;
  overflow: auto;
  border-top: 1px solid var(--border);
}
.bottomResize {
  position: sticky;
  top: 0;
  display: block;
  height: 8px;
  margin-bottom: -8px;
  z-index: 2;
  cursor: row-resize;
  touch-action: none;
}
.bottom[data-collapsed="true"] {
  height: auto;
  min-height: 0;
  overflow: hidden;
}
.bottomResize:hover,
.bottomResize:focus-visible {
  background: color-mix(in srgb, var(--primary) 25%, transparent);
  outline: 2px solid var(--ring);
  outline-offset: -2px;
}
.backdrop {
  position: fixed;
  inset: 0;
  z-index: var(--layer-overlay, 60);
  background: rgb(0 0 0 / 40%);
  transition: opacity var(--motion-drawer) ease-out;
}
.drawer {
  position: fixed;
  inset: 0 0 0 auto;
  z-index: var(--layer-overlay, 60);
  display: flex;
  flex-direction: column;
  width: min(320px, calc(100% - 32px));
  background: var(--surface);
  border-left: 1px solid var(--border);
  box-shadow: var(--shadow-floating);
  outline: none;
  transition: transform var(--motion-drawer) ease-out;
}
.backdrop[data-starting-style],
.backdrop[data-ending-style] {
  opacity: 0;
}
.drawer[data-starting-style],
.drawer[data-ending-style] {
  transform: translateX(100%);
}
@container workspace-shell (min-width: 1024px) {
  .sidebar {
    width: var(--sidebar-current-width, var(--workspace-sidebar-width));
  }
  .shell[data-sidebar-collapsed="true"] .sidebar {
    width: var(--workspace-sidebar-collapsed);
  }
  .sidebarToggle {
    display: inline-flex;
  }
}
@media (max-width: 767px) {
  .drawer {
    width: min(360px, calc(100% - 32px));
  }
}
@media (pointer: coarse) {
  .resizeHandle {
    left: -8px;
    width: 16px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .drawer,
  .backdrop {
    transition: none;
  }
}

.sidebarResize {
  display: none;
  flex-shrink: 0;
  width: 8px;
  cursor: col-resize;
  touch-action: none;
}
.sidebarResize:hover,
.sidebarResize:focus-visible {
  background: color-mix(in srgb, var(--primary) 25%, transparent);
  outline: 2px solid var(--ring);
  outline-offset: -2px;
}
@container workspace-shell (min-width:1024px) {
  .sidebarResize {
    display: block;
  }
}
@media (pointer: coarse) {
  .sidebarResize {
    width: 44px;
  }
}
